def comps_of(i, vals):
    h,w=len(i),len(i[0])
    seen=[[False]*w for _ in range(h)]; cl=[]
    for r in range(h):
        for c in range(w):
            if i[r][c] in vals and not seen[r][c]:
                st=[(r,c)]; comp=[]
                while st:
                    y,x=st.pop()
                    if seen[y][x]: continue
                    seen[y][x]=True; comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and i[ny][nx] in vals and not seen[ny][nx]:
                                st.append((ny,nx))
                cl.append(comp)
    return cl

