        seen=set(); out=[]
        for i in range(H):
            for j in range(W):
                if cols[i][j]!=maj and (i,j) not in seen:
                    q=[(i,j)]; comp=[]; seen.add((i,j)); val=cols[i][j]
                    while q:
                        x,y=q.pop(); comp.append((x,y))
                        for dx in(-1,0,1):
                            for dy in(-1,0,1):
                                nx,ny=x+dx,y+dy
                                if 0<=nx<H and 0<=ny<W and cols[nx][ny]==val and (nx,ny) not in seen:
                                    seen.add((nx,ny)); q.append((nx,ny))
                    out.append(comp)
        return out
    cs=comps(A)
