    T=[[A[r][c] for c in range(lb,rb)] for r in range(tb,eb)]
    th, tw = eb-tb, rb-lb
    out=[row[:] for row in A]
    for i in range(H):
        for j in range(W):
            if A[i][j]!=maj:
                out[i][j]=T[i%th][j%tw]
    return out
